  return 'M'+p(R,a0)+'A'+R+' '+R+' 0 '+big+' 1 '+p(R,a1)+'L'+p(r,a1)+'A'+r+' '+r+' 0 '+big+' 0 '+p(r,a0)+'Z';
};

setMainView:
function setMainView(v,skipFade){
  if(_mainView===v){_mvSync();return;}
  var vt=!!(document.startViewTransition&&!document.hidden),commit=function(){
    _mainView=v;
    try{sessionStorage.setItem('mvView',v);}catch(_e){}
    _mvApply();
    if(!skipFade&&!vt)try{_mvSlideLeft(v==='biz'?1:-1);}catch(_e){}
  };
  if(vt)try{document.startViewTransition(commit);}catch(_e){commit();}else commit();
}
